/**
 * 改造自 shadcn 原装 base-lyra tabs（https://ui.shadcn.com/r/styles/base-lyra/tabs.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021）。`Tabs` 收 `motion`，经 context 交给 `TabsList` 与 `TabsTrigger`。
 *    缺省 `indicator`：`TabsList` 里渲染 Base UI 的 `Tabs.Indicator`（`data-motion="indicator"`），
 *    选中的底色（default 变体）或下划线（line 变体）由它画，切换时滑过去；`TabsTrigger` 不再画选中的底色与下划线。
 *    `none` 与上游完全一致：选中的底色与下划线画在 `TabsTrigger` 上，切换时直接跳。
 * 2. `TabsList` 在 `indicator` 下加 `relative isolate`，给滑块定位并让它落在文字下面。
 * 3. 不导出 `tabsListVariants`：cva 不是公开 API（SKILL 第 5 步），本系统里没有调用处。
 * 此外只有格式化与两条 Biome 豁免注释，其余类名逐字保留（选中态的类按 motion 拆成两组，内容不变）。
 */
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import { createContext, use } from "react";

/**
 * 标签页支持的动效预设（ADR 0021）。缺省 `indicator`。
 * - `indicator`：选中的底色或下划线从上一个标签滑到新标签，200ms。
 * - `none`：Lyra 原版，选中态直接跳到新标签。
 */
type TabsMotion = "none" | "indicator";

const TabsMotionContext = createContext<TabsMotion>("indicator");

function Tabs({
  className,
  orientation = "horizontal",
  motion = "indicator",
  ...props
}: TabsPrimitive.Root.Props & { motion?: TabsMotion }) {
  return (
    <TabsMotionContext value={motion}>
      <TabsPrimitive.Root
        data-slot="tabs"
        data-orientation={orientation}
        className={cn("group/tabs flex gap-2 data-horizontal:flex-col", className)}
        {...props}
      />
    </TabsMotionContext>
  );
}

const tabsListVariants = cva(
  // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的内边距。
  "group/tabs-list inline-flex w-fit items-center justify-center rounded-none p-[3px] text-muted-foreground group-data-horizontal/tabs:h-8 group-data-vertical/tabs:h-fit group-data-vertical/tabs:flex-col data-[variant=line]:rounded-none",
  {
    variants: {
      variant: {
        default: "bg-muted",
        line: "gap-1 bg-transparent",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

/** 滑块的外观：default 变体是选中的底色，line 变体是下划线。位置与尺寸取 Base UI 给的 --active-tab-*。 */
const INDICATOR_CLASS = {
  default:
    "top-0 left-0 h-(--active-tab-height) w-(--active-tab-width) translate-x-(--active-tab-left) translate-y-(--active-tab-top) border border-transparent bg-background dark:border-input dark:bg-input/30",
  line: "bg-foreground group-data-horizontal/tabs:-bottom-px group-data-horizontal/tabs:left-0 group-data-horizontal/tabs:h-0.5 group-data-horizontal/tabs:w-(--active-tab-width) group-data-horizontal/tabs:translate-x-(--active-tab-left) group-data-vertical/tabs:top-0 group-data-vertical/tabs:-right-px group-data-vertical/tabs:h-(--active-tab-height) group-data-vertical/tabs:w-0.5 group-data-vertical/tabs:translate-y-(--active-tab-top)",
} as const;

function TabsList({
  className,
  variant = "default",
  children,
  ...props
}: TabsPrimitive.List.Props & VariantProps<typeof tabsListVariants>) {
  const motion = use(TabsMotionContext);
  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      data-variant={variant}
      className={cn(
        tabsListVariants({ variant }),
        motion === "indicator" && "relative isolate",
        className,
      )}
      {...props}
    >
      {motion === "indicator" ? (
        <TabsPrimitive.Indicator
          data-slot="tabs-indicator"
          data-motion="indicator"
          className={cn("absolute -z-10", INDICATOR_CLASS[variant ?? "default"])}
        />
      ) : null}
      {children}
    </TabsPrimitive.List>
  );
}

/** 选中态：`none` 画在标签上（与上游一致）；`indicator` 只换文字色，底色与下划线交给滑块。 */
const TRIGGER_ACTIVE_CLASS: Record<TabsMotion, string> = {
  none: cn(
    "group-data-[variant=line]/tabs-list:bg-transparent group-data-[variant=line]/tabs-list:data-active:bg-transparent dark:group-data-[variant=line]/tabs-list:data-active:border-transparent dark:group-data-[variant=line]/tabs-list:data-active:bg-transparent",
    "data-active:bg-background data-active:text-foreground dark:data-active:border-input dark:data-active:bg-input/30 dark:data-active:text-foreground",
    "group-data-[variant=line]/tabs-list:data-active:after:opacity-100",
  ),
  indicator: "data-active:text-foreground dark:data-active:text-foreground",
};

function TabsTrigger({ className, ...props }: TabsPrimitive.Tab.Props) {
  const motion = use(TabsMotionContext);
  return (
    <TabsPrimitive.Tab
      data-slot="tabs-trigger"
      className={cn(
        // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的高度、竖排内边距与焦点环。
        "relative inline-flex h-[calc(100%-1px)] flex-1 items-center justify-center gap-1.5 rounded-none border border-transparent px-1.5 py-0.5 text-xs font-medium whitespace-nowrap text-foreground/60 transition-all group-data-vertical/tabs:w-full group-data-vertical/tabs:justify-start group-data-vertical/tabs:py-[calc(--spacing(1.25))] hover:text-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-1 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 has-data-[icon=inline-end]:pr-1 has-data-[icon=inline-start]:pl-1 aria-disabled:pointer-events-none aria-disabled:opacity-50 dark:text-muted-foreground dark:hover:text-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        TRIGGER_ACTIVE_CLASS[motion],
        // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的下划线位置。
        "after:absolute after:bg-foreground after:opacity-0 after:transition-opacity group-data-horizontal/tabs:after:inset-x-0 group-data-horizontal/tabs:after:bottom-[-5px] group-data-horizontal/tabs:after:h-0.5 group-data-vertical/tabs:after:inset-y-0 group-data-vertical/tabs:after:-right-1 group-data-vertical/tabs:after:w-0.5",
        className,
      )}
      {...props}
    />
  );
}

function TabsContent({ className, ...props }: TabsPrimitive.Panel.Props) {
  return (
    <TabsPrimitive.Panel
      data-slot="tabs-content"
      className={cn("flex-1 text-xs/relaxed outline-none", className)}
      {...props}
    />
  );
}

export { Tabs, TabsContent, TabsList, type TabsMotion, TabsTrigger };
